// Generates core/src/help-data.js (the console Help tab) from docs/help.md. The same file feeds the owner README that
// bootstrap writes. `node tools/build_help.mjs` writes; `--check` exits 1 when the generated file is stale.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('../', import.meta.url));
export const SOURCE = 'docs/help.md';
export const TARGET = 'core/src/help-data.js';

export function parseHelp(md) {
  const sections = [];
  let cur = null;
  for (const line of md.replace(/\r\n/g, '\n').split('\n')) {
    const h = /^##\s+(.+?)\s*$/.exec(line);
    if (h) { cur = { id: h[1].toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''), title: h[1], lines: [] }; sections.push(cur); continue; }
    if (cur) cur.lines.push(line);
  }
  return sections.map(s => ({ id: s.id, title: s.title, text: s.lines.join('\n').trim().split(/\n{2,}/).map(p => p.replace(/\n/g, ' ').trim()).filter(Boolean).join('\n\n') }))
    .filter(s => s.text);
}

export function render(md) {
  return '// SPDX-License-Identifier: LicenseRef-Ultrastable-USL-1.0\n'
    + '// Copyright (c) 2026 Rowan Brad Quni-Gudzinas. Non-commercial use free; commercial use requires a license. See LICENSE.\n'
    + `// Generated by tools/build_help.mjs from ${SOURCE}. Do not edit; edit the source and rerun.\n`
    + `export const HELP_SECTIONS = ${JSON.stringify(parseHelp(md), null, 2)};\n`;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const out = render(readFileSync(ROOT + SOURCE, 'utf8'));
  if (process.argv.includes('--check')) {
    let cur = '';
    try { cur = readFileSync(ROOT + TARGET, 'utf8'); } catch { /* missing counts as stale */ }
    if (cur.replace(/\r\n/g, '\n') !== out) { console.error(`${TARGET} is stale: run node tools/build_help.mjs`); process.exit(1); }
    console.log(`${TARGET} is current`);
  } else { writeFileSync(ROOT + TARGET, out); console.log(`wrote ${TARGET}`); }
}
